sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var hostile = {};
  hostile["X'; Add-ADGroupMember -Identity 'Domain Admins' -Members 'svc'; #"] = 'value';
  var r = ad.setUserAttributesAd('jdoe', hostile);
  if (r.ok) { stepResult.setFailed('injection-shaped parameter name was accepted (P0-1 regressed)'); return; }
  if (('' + r.error).indexOf('illegal parameter name') === -1) {
    stepResult.setFailed('refused, but not by the name validator: ' + r.error); return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var r = ad.setUserAttributesAd('jdoe', { scriptPath: '\\\\evil\\share\\run.bat' });
  if (r.ok) { stepResult.setFailed('non-allowlisted parameter accepted - allowlist is not closed'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var r = ad.setUserAttributesAd('jdoe', { Identity: 'Administrator', title: 'x' });
  if (r.ok) { stepResult.setFailed('caller-supplied Identity was accepted (P0-2 regressed)'); return; }
  if (('' + r.error).indexOf('reserved parameter') === -1) {
    stepResult.setFailed('refused, but not as a reserved-parameter override: ' + r.error); return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var r = ad.setPasswordAd('jdoe', { tempPassword: 'Sup3rSecret!' });
  if (r.ok) { stepResult.setFailed('setPasswordAd accepted password material (P0-3 regressed)'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
